import { existsSync, lstatSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { parse } from "smol-toml";

import type { Output } from "../outputs.js";
import {
  exists,
  getKey,
  linkOf,
  readJson,
  same,
  withoutBlock,
} from "./_shared.js";

const PREDECESSORS = [
  "by sync-claude-projection.sh",
  "AUTO-GENERATED by scripts/agent/project.mjs",
];

function objectKeys(value: unknown): string[] {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    return [];
  }
  return Object.keys(value);
}

// Protect unmanaged files so projection cannot overwrite another tool's configuration.
export function replaceable(
  root: string,
  output: Output,
  owned: Set<string>,
): boolean {
  if (output.kind === "json") {
    if (output.file === "opencode.json") {
      let parent: unknown = readJson(join(root, output.file));
      for (const part of output.key.slice(0, -1)) {
        if (parent === undefined) break;
        if (
          parent === null ||
          typeof parent !== "object" ||
          Array.isArray(parent)
        )
          return false;
        parent = (parent as Record<string, unknown>)[part];
      }
      if (
        parent !== undefined &&
        (parent === null || typeof parent !== "object" || Array.isArray(parent))
      )
        return false;
    }
    const guarded =
      output.key[0] === "mcpServers" || output.file === "opencode.json";
    if (!guarded || owned.has(output.path)) {
      return true;
    }
    const existing = getKey(readJson(join(root, output.file)), output.key);
    return existing === undefined || same(existing, output.value);
  }
  if (output.kind === "block") {
    const absolute = join(root, output.file);
    const text = existsSync(absolute) ? readFileSync(absolute, "utf8") : "";
    const outside = parse(withoutBlock(text));
    const proposed = parse(output.content);
    return !["mcp_servers", "marketplaces", "plugins"].some((table) => {
      const existing = objectKeys(outside[table]);
      return objectKeys(proposed[table]).some((name) =>
        existing.includes(name),
      );
    });
  }
  if (owned.has(output.path)) return true;
  const abs = join(root, output.path);
  if (!exists(abs)) return true;
  const target = linkOf(abs);
  if (target !== null) {
    return output.kind === "link" && target === output.target;
  }
  if (lstatSync(abs).isDirectory()) return false;
  const text = readFileSync(abs, "utf8");
  if (output.kind === "file" && text === output.content) return true;
  return PREDECESSORS.some((mark) => text.includes(mark));
}
